package policyset
import("errors";"fmt";"sort")
type Command struct{ID string `json:"id"`;Executable string `json:"executable"`;Args []string `json:"args"`;Required bool `json:"required"`}
type Policy struct{SchemaVersion string `json:"schema_version"`;Revision string `json:"revision"`;Commands []Command `json:"commands"`}
type Resolved struct{SchemaVersion string `json:"schema_version"`;OrganizationRevision string `json:"organization_revision"`;RepositoryRevision string `json:"repository_revision"`;Commands []ResolvedCommand `json:"commands"`;Delta []string `json:"delta"`}
type ResolvedCommand struct{Command;Provenance string `json:"provenance"`}
func Resolve(org,repo Policy)(Resolved,error){if org.SchemaVersion!="1.0.0"||repo.SchemaVersion!="1.0.0"||org.Revision==""||repo.Revision==""{return Resolved{},errors.New("policy metadata is incomplete")};seen:=map[string]Command{};out:=Resolved{SchemaVersion:"1.0.0",OrganizationRevision:org.Revision,RepositoryRevision:repo.Revision,Commands:[]ResolvedCommand{},Delta:[]string{}};for _,c:=range org.Commands{if c.ID==""||c.Executable==""||seen[c.ID].ID!=""{return Resolved{},errors.New("organization policy has invalid or duplicate command")};seen[c.ID]=c;out.Commands=append(out.Commands,ResolvedCommand{c,"organization"})};for _,c:=range repo.Commands{if c.ID==""||c.Executable==""{return Resolved{},errors.New("repository policy has invalid command")};if base,ok:=seen[c.ID];ok{if base.Executable!=c.Executable||fmt.Sprint(base.Args)!=fmt.Sprint(c.Args){return Resolved{},fmt.Errorf("conflicting command id %q",c.ID)};if base.Required&&!c.Required{return Resolved{},fmt.Errorf("repository weakens required command %q",c.ID)};continue};seen[c.ID]=c;out.Commands=append(out.Commands,ResolvedCommand{c,"repository"});out.Delta=append(out.Delta,c.ID)};sort.Slice(out.Commands,func(i,j int)bool{return out.Commands[i].ID<out.Commands[j].ID});sort.Strings(out.Delta);return out,nil}
